            "**Расходные материалы** — тонер, чернила, фотобарабан, печатающие головки, бумага. Самая большая и растущая во времени статья.",
            "**Сервис** — профилактика, выезды инженера, запчасти, ремонт.",
            "**Простои** — стоимость часа простоя бригады из-за отсутствия чертежа или неработающего МФУ в вагончике. В строительстве это самая дорогая и часто неучтённая статья.",
            "**Энергопотребление, ИТ-поддержка, амортизация** — косвенные, но реальные расходы."
