        "Эмпирическое правило: если стоимость ремонта превышает 50 % стоимости нового устройства сопоставимого класса — выгоднее заменить. Особенно это актуально для техники, выработавшей ресурс (3–5 лет эксплуатации, исчерпанный ресурс узлов). Ремонт одного узла на старом аппарате часто предваряет цепочку следующих поломок, и суммарные расходы превышают цену нового МФУ с гарантией.",
        "Для строительной компании с несколькими аппаратами выгоднее не ремонтировать каждый по факту поломки, а заключить сервисный договор с превентивным обслуживанием и плановой заменой техники по выработке ресурса. Это превращает непредсказуемые расходы на ремонты в фиксированную и предсказуемую строку бюджета."
