 "**Фотобарабан** формирует изображение. Со временем на нём появляются царапины, потёртости, износ покрытия и следы от старого тонера, отсюда вертикальные полосы, повтор изображения, серый фон, пятна и неравномерная плотность. Засыпать новый тонер в картридж с изношенным барабаном, всё равно что залить хорошее топливо в автомобиль с неисправным зажиганием.",
 "**Ракель** очищает барабан от остатков тонера после прохождения листа. Если кромка изношена, старый тонер остаётся на поверхности и переносится на следующие страницы: серый фон, продольные полосы, повторяющийся текст, грязные края. На глаз ракель оценить нельзя, кромка может потерять геометрию незаметно.",
 "**Зарядный ролик** отвечает за равномерный заряд барабана. Загрязнённый или изношенный ролик даёт серый фон, неравномерную плотность, пропуски и полосы. Поверхностное загрязнение лечится протиркой, потеря свойств, только заменой.",
