 "Представьте канализацию коттеджного посёлка. Рассчитана на воду. А вы в неё годами сбрасываете... ну, скажем, растворимый кофе и гравий. Что произойдёт? Правильно: труба забьётся, насос будет рваться, а в конце концов сгорит. С принтером то же самое, только вместо трубы узкий канал с винтовым шнеком, а вместо насоса, моторчик, крутящий маленькую пластиковую шестерёнку.",
