// Хелпер для поиска статьи по slug
 export const getArticleBySlug = (slug) => articles.find((a) => a.slug === slug);

export const getRelatedCases = (article, limit = 3) => {
  const tags = new Set(article.tags || []);
  return articles
    .filter((a) => a.isCase && a.slug !== article.slug)
    .map((a) => ({ a, score: (a.tags || []).filter((t) => tags.has(t)).length }))
    .sort((x, y) => y.score - x.score || y.a.date.localeCompare(x.a.date))
    .slice(0, limit)
    .map(({ a }) => a);
};